 1, L // 2), 1.0)], num_qubits=L\n)\n\n# Generate an initial state\nL = hamiltonian.num_qubits\ninitial_state = QuantumCircuit(L)\nfor i in range(L):\n    if i % 2:\n        initial_state.x(i)\n'})}),"\n",(0,i.jsx)(s.h3,{id:"step-1-map-classical-inputs-to-a-quantum-problem",children:"Krok 1: P\u0159evod klasick\xfdch vstup\u016f na kvantov\xfd probl\xe9m"}),"\n",(0,i.jsx)(s.p,{children:"Pro tento v\u011bt\u0161\xed probl\xe9m za\u010d\xedn\xe1me konstrukc\xed Hamiltoni\xe1nu pro XXZ model s 50 m\xedsty, p\u0159i\u010dem\u017e definujeme interakce spin-spin a extern\xed magnetick\xe1 pole nap\u0159\xed\u010d v\u0161emi m\xedsty. Pot\xe9 postupujeme ve t\u0159ech hlavn\xedch kroc\xedch:"}),"\n",(0,i.jsxs)(s.ol,{children:["\n",(0,i.jsxs)(s.li,{children:[(0,i.jsx)(s.strong,{children:"Vygeneruj optimalizovan\xfd AQC Circuit"}),": Pou\u017eij Trotterizaci pro p\u0159ibl\xed\u017een\xed po\u010d\xe1te\u010dn\xed evoluce, pak tento segment komprimuj, abys sn\xed\u017eil hloubku Circuit."]}),"\n",(0,i.jsxs)(s.li,{children:[(0,i.jsx)(s.strong,{children:"Vytvo\u0159 zb\xfdvaj\xedc\xed Circuit \u010dasov\xe9 evoluce"}),": Zachy\u0165 zb\xfdvaj\xedc\xed \u010dasovou evoluci p\u0159esahuj\xedc\xed po\u010d\xe1te\u010dn\xed segment."]}),"\n",(0,i.jsxs)(s.li,{children:[(0,i.jsx)(s.strong,{children:"Spoj Circuity"}),": Slou\u010d optimalizovan\xfd AQC Circuit se zb\xfdvaj\xedc\xedm evolu\u010dn\xedm Circuitem, \u010d\xedm\u017e vytvo\u0159\xed\u0161 \xfapln\xfd Circuit \u010dasov\xe9 evoluce p\u0159ipraven\xfd ke spu\u0161t\u011bn\xed."]}),"\n"]}),"\n",(0,i.jsxs)(s.p,{children:["The primary objective is to simulate time evolution for a model Hamiltonian with a reduced circuit depth. This is achieved using the ",(0,i.jsx)(s.strong,{children:"AQC-Tensor"})," Qiskit addon, ",(0,i.jsx)(s.a,{href:"https://github.com/Qiskit/qiskit-addon-aqc-tensor",children:"qiskit-addon-aqc-tensor"}),", which leverages tensor networks, specifically matrix product states (MPS), to compress and optimize th